INSERT INTO routes (from_hub, to_hub, distance_km, avg_travel_hours)
SELECT ha.id, hb.id, e.km, e.hrs
  FROM edge e JOIN hubs ha ON ha.code = e.a JOIN hubs hb ON hb.code = e.b
UNION ALL
SELECT hb.id, ha.id, e.km, e.hrs
  FROM edge e JOIN hubs ha ON ha.code = e.a JOIN hubs hb ON hb.code = e.b;

-- Sample shipments  (each row is a real Olist order; see order_id comment)
INSERT INTO shipments
    (tracking_no, origin_hub, dest_hub, weight_kg, freight_value, status,
     created_at, promised_at, delivered_at)
SELECT s.tracking_no, ho.id, hd.id, s.weight_kg, s.freight_value, s.status,
       s.created_at, s.promised_at, s.delivered_at
FROM (
    VALUES
      ('SS0000000001','PR','RJ', 5.65, 31.46, 'DELIVERED', '2017-08-07 19:38:03', '2017-08-31 00:00:00', '2017-08-18 18:19:28'),  -- order a6bf5dacdd39…
