      ('SS0000000004','SP','DF', 0.27, 15.32, 'DELIVERED', '2017-11-20 12:47:43', '2017-12-11 00:00:00', '2017-12-04 20:42:42'),  -- order 532724cb017a…
      ('SS0000000005','SP','MG', 1.10, 18.02, 'DELIVERED', '2017-09-26 12:10:26', '2017-10-26 00:00:00', '2017-10-06 21:34:13'),  -- order 0872d0faafe0…
      ('SS0000000006','SP','MG', 2.00, 26.67, 'DELIVERED', '2018-01-16 11:20:27', '2018-02-08 00:00:00', '2018-02-05 21:09:02'),  -- order 3be018db2ccc…
      ('SS0000000007','SP','MG', 0.95, 19.32, 'DELIVERED', '2018-04-05 11:04:01', '2018-04-25 00:00:00', '2018-04-23 14:06:48'),  -- order e7b90dc72945…
      ('SS0000000008','RJ','SP', 0.44, 16.74, 'DELIVERED', '2017-09-18 14:04:37', '2017-10-09 00:00:00', '2017-09-26 20:15:59'),  -- order a1c075cf51b2…
      ('SS0000000009','RO','BA', 17.30, 75.12, 'DELIVERED', '2017-04-29 14:34:26', '2017-06-13 00:00:00', '2017-05-15 04:43:56'),  -- order 94179e454a57…
      ('SS0000000010','SP','RJ', 1.02, 18.56, 'DELIVERED', '2018-06-24 09:48:14', '2018-07-19 00:00:00', '2018-06-28 22:58:26'),  -- order 5570d1c57d34…
      ('SS0000000011','MG','SP', 0.20, 14.32, 'IN_TRANSIT', '2018-08-18 06:29:22', '2018-08-29 00:00:00', NULL),  -- order 14a05c02d483… (not yet delivered)
      ('SS0000000012','SP','RJ', 10.75, 67.55, 'IN_TRANSIT', '2018-04-01 18:31:24', '2018-04-20 00:00:00', NULL),  -- order bfcb17110907… (not yet delivered)
      ('SS0000000013','SP','PR', 2.70, 26.72, 'IN_TRANSIT', '2018-04-02 11:24:47', '2018-04-25 00:00:00', NULL),  -- order c4844a648661… (not yet delivered)
