) AS s(tracking_no, o_code, d_code, weight_kg, freight_value, status,
       created_at, promised_at, delivered_at)
JOIN hubs ho ON ho.code = s.o_code
JOIN hubs hd ON hd.code = s.d_code;

-- Tracking events for a few shipments (real Olist timestamps).
-- We only know the origin (seller) and destination (customer) states, so the
-- scan history reflects exactly those hops — no intermediate hub is invented.
INSERT INTO tracking_events (shipment_id, hub_id, event_type, event_time)
SELECT s.id, h.id, e.event_type, e.event_time
FROM shipments s
JOIN (
    VALUES
      ('PR','PICKED_UP', '2017-08-08 19:45:14'),
      ('PR','DEPARTED_HUB', '2017-08-09 16:47:55'),
      ('RJ','ARRIVED_AT_HUB', '2017-08-09 16:47:55'),
      ('RJ','OUT_FOR_DELIVERY', '2017-08-18 18:19:28'),
      ('RJ','DELIVERED', '2017-08-18 18:19:28')
) AS e(hub_code, event_type, event_time) ON TRUE
JOIN hubs h ON h.code = e.hub_code
WHERE s.tracking_no = 'SS0000000001';

INSERT INTO tracking_events (shipment_id, hub_id, event_type, event_time)
SELECT s.id, h.id, e.event_type, e.event_time
